		if (slot < 0 || namespaceWindowNext[slot] != 0L) {
			return;
		}
		if (namespaceReferences[slot] == Long.MAX_VALUE) {
			disabled = true;
			return;
		}
		namespaceReferences[slot]++;
		namespaceWindowNext[slot] = windowHead == 0L ? 1L : windowHead;
		windowHead = namespace;
